const STRATEGIES = ['escape', 'brake', 'hyperspace', 'aim'];

function spExecute(s, strategy) {
  const sh = s.ship;
  if (strategy === 'hyperspace') return { hyper: s.frame % 2 === 0 };
  const T = spThreats(s);
  let plan = null, hitBy = null;
  if (strategy === 'escape') {
    const stay = spSimulate(s, T, null, SP_HORIZON);      // what hits if no key is pressed
    if (stay.ttc !== Infinity) {
      const { bestSafe, bestLate } = spDodgeSearch(s, T); // 16 headings x 5 thrust lengths
      plan = bestSafe ? bestSafe.p : bestLate.p;
      hitBy = stay.by;
    }
  } else if (strategy === 'brake') {
    const speed = Math.hypot(sh.vx, sh.vy);
    if (speed >= 1.5) plan = spBrakePlan(sh, speed);      // thrust against the drift
  }
