function strategyPilot(s) {
  const retry = Date.now() - strategyLastFailTime > 3000;
  if (!strategyPending && (strategyServerOnline || retry)) {
    strategyPending = true;
    fetch(STUDENT_ENDPOINT, { method: 'POST',
        body: JSON.stringify({ state: layaFrameState(s, 4, false) }) })
      .then(r => r.json())
      .then(data => {
        const c = data.answers.action.choice;
        strategyLast = { choice: STRATEGIES.includes(c) ? c : 'aim' };
      })
      .catch(() => { strategyLast = { choice: null }; })   // server offline
      .finally(() => { strategyPending = false; });
  }
  if (strategyLast.choice === null) return smartPilot(s);  // fallback
  return spExecute(s, strategyLast.choice);                 // every tick
}
